/*
  This file is used to store unsecure, application-specific data common to all
  environments.

  Additional Environent Variables:
  - CONNECT_PREF: should have a value of 'cr' (default), or 'direct'. This is
    used by helia-coord to select a connection preference between peers. Servers
    with an ip4 or ip6 address should use 'direct'.
  - BOOTSTRAP_SERVERS: comma-delimited list of peer multiaddrs, replacing the
    hard-coded DEFAULT_BOOTSTRAP_PEERS list in helia-coord. Unset uses those
    defaults. STARTUP_PEERS is still accepted as a legacy alias. Format and
    example in the README.
  - ANNOUNCE_MULTIADDRS: comma-delimited list of multiaddrs added to this node's
    announcement (read directly by helia-coord >= 2.1.0, so there is no config
    key for it). Use it when the public address can not be auto-detected: behind
    a NAT, a firewall, or a proxy such as a wireguard tunnel. Format and example
    in the README.
*/

/* eslint  no-unneeded-ternary:0 */

// Hack to get __dirname back.
// https://blog.logrocket.com/alternatives-dirname-node-js-es-modules/
import * as url from 'url'

// Get the version from the package.json file.
import { readFileSync } from 'fs'
const __dirname = url.fileURLToPath(new URL('.', import.meta.url))
const pkgInfo = JSON.parse(readFileSync(`${__dirname.toString()}/../../package.json`))

const version = pkgInfo.version

const ipfsCoordName = process.env.COORD_NAME
  ? process.env.COORD_NAME
  : 'ipfs-bch-wallet-service'

// Parse the comma-delimited peer list. BOOTSTRAP_SERVERS is the current name;
// STARTUP_PEERS is honoured as a legacy alias.
//
// Returns undefined (never []) when unset or blank: helia-coord does
// `localConfig.bootstrapPeers || DEFAULT_BOOTSTRAP_PEERS`, and [] is truthy, so
// passing an empty array would silently disable bootstrap discovery.
//
// A malformed entry throws at startup, where it can be fixed, instead of
// surfacing as a cryptic libp2p failure minutes later.
function parseBootstrapPeers () {
  const raw = process.env.BOOTSTRAP_SERVERS || process.env.STARTUP_PEERS

  const peers = (raw || '')
    .split(',')
    .map(peer => peer.trim())
    .filter(peer => peer.length > 0)

  if (peers.length === 0) return undefined

  const invalid = peers.find(peer => !peer.startsWith('/'))
  if (invalid) {
    throw new Error(
      `BOOTSTRAP_SERVERS contains an invalid multiaddr: '${invalid}'. Each entry must start with '/', e.g. /ip4/1.2.3.4/tcp/4101/p2p/12D3KooW...`
    )
  }

  return peers
}

export default {
  // Configure TCP port.
  port: process.env.PORT || 5031,

  // Password for HTML UI that displays logs.
  logPass: 'test',

  // Email server settings if nodemailer email notifications are used.
  emailServer: process.env.EMAILSERVER
    ? process.env.EMAILSERVER
    : 'mail.someserver.com',
  emailUser: process.env.EMAILUSER
    ? process.env.EMAILUSER
    : 'noreply@someserver.com',
  emailPassword: process.env.EMAILPASS
    ? process.env.EMAILPASS
    : 'emailpassword',

  // Enable or Disable the usage of Mongo DB.
  noMongo: process.env.NO_MONGO ? true : false,

  // BEGIN WALLET CONFIGURATION

  // BCH Mnemonic for generating encryption keys and payment address
  mnemonic: process.env.MNEMONIC ? process.env.MNEMONIC : '',

  // (Optional) use a wallet file generated by psf-bch-wallet.
  walletFile: process.env.WALLET_FILE
    ? process.env.WALLET_FILE
    : `${__dirname.toString()}/../../wallet.json`,

  // Wallet Configuration
  // Default value: web3 - connect to bch-api through web 3 JSON RPC over IPFS.
  // Alternate value: web2 - connect to bch-api through a web 2 REST API over HTTP.
  walletInterface: process.env.WALLET_INTERFACE ? process.env.WALLET_INTERFACE : 'web3',

  // Wallet API Server
  // Default web2 server: https://api.fullstack.cash/v5/
  // Default web3 server: https://free-bch.fullstack.cash/
  apiServer: process.env.WALLET_INTERFACE === 'web2'
    ? (
        process.env.APISERVER
          ? process.env.APISERVER
          : 'https://bch.fullstack.cash/v6/'
      )
    : 'https://free-bch.fullstack.cash/',

  // Basic Authentication Password for connecting to bch-api through a web 2
  // REST API over HTTP.
  authPass: process.env.WALLET_AUTH_PASS
    ? process.env.WALLET_AUTH_PASS
    : '',

  // FullStack.cash account information, used for automatic JWT handling.
  getJwtAtStartup: process.env.GET_JWT_AT_STARTUP ? true : false,
  authServer: process.env.AUTHSERVER
    ? process.env.AUTHSERVER
    : 'https://auth.fullstack.cash',
  fullstackLogin: process.env.FULLSTACKLOGIN
    ? process.env.FULLSTACKLOGIN
    : 'demo@demo.com',
  fullstackPassword: process.env.FULLSTACKPASS
    ? process.env.FULLSTACKPASS
    : 'demo',

  // END WALLET CONFIGURATION

  // BEGIN IPFS CONFIGURATION

  // Debug verbosity level of helia-coord.
  // 0 = no debug logs. 3 = maximum logs.
  debugLevel: process.env.DEBUG_LEVEL ? parseInt(process.env.DEBUG_LEVEL) : 2,

  // Enable/Disable the IPFS node at startup. Enabled by default.
  useIpfs: process.env.DISABLE_IPFS ? false : true,

  isCircuitRelay: process.env.ENABLE_CIRCUIT_RELAY ? true : false,
  // SSL domain used for websocket connection via browsers.
  crDomain: process.env.CR_DOMAIN ? process.env.CR_DOMAIN : '',

  // Information passed to other IPFS peers about this node.
  apiInfo: 'https://ipfs-service-provider.fullstack.cash/',

  // JSON-LD and Schema.org schema with info about this app.
  announceJsonLd: {
    '@context': 'https://schema.org/',
    '@type': 'WebAPI',
    name: ipfsCoordName,
    version,
    protocol: 'ipfs-file-pin-service',
    description:
      'Helia node that pins IPFS files. Activated by psf-slp-indexer.',
    documentation: 'https://ipfs-file-pin-service.fullstack.cash/',
    provider: {
      '@type': 'Organization',
      name: 'Permissionless Software Foundation',
      url: 'https://PSFoundation.cash'
    },

    // If this node has an IP4 address or domain name used to provide a REST API.
    web2Api: process.env.WEB2_API ? process.env.WEB2_API : null
  },

  // IPFS Ports
  ipfsTcpPort: process.env.IPFS_TCP_PORT ? process.env.IPFS_TCP_PORT : 4001,
  ipfsWsPort: process.env.IPFS_WS_PORT ? process.env.IPFS_WS_PORT : 4003,
  ipfsWebRtcPort: process.env.IPFS_WEB_RTC_PORT ? process.env.IPFS_WEB_RTC_PORT : 4005,
  connectPref: process.env.CONNECT_PREF, // Used in helia-coord to select connection preference.

  // The IPFS node is embedded via helia-coord. Ports for the embedded node are
  // set above.

  chatPubSubChan: 'psf-ipfs-chat-001',

  // Peer list used for bootstrap discovery, replacing helia-coord's hard-coded
  // DEFAULT_BOOTSTRAP_PEERS. Undefined (default) keeps those defaults.
  bootstrapPeers: parseBootstrapPeers(),

  useWebRtc: process.env.USE_WEB_RTC ? process.env.USE_WEB_RTC : false,

  // END IPFS CONFIGURATION

  // BEGIN FILE PIN CONFIGURATION

  // Maximum allowable files size, in bytes.
  maxPinSize: 100000000,

  // BCH payment configuration (PS010 v2.0.0, Phase 1).
  //
  // Clean break: pin payment is validated as a BCH payment only. There is no
  // PSF-token proof-of-burn path, no PS009 write-price lookup and no token
  // fallback price. See dev-docs/pin-claim-processing.md.

  // Address that receives pin payments. Served by GET /ipfs/payment-address and
  // used to validate every claim. Defaults to the PSF 'pinning' wallet.
  payoutAddress: process.env.PAYOUT_ADDRESS
    ? process.env.PAYOUT_ADDRESS
    : 'bitcoincash:qrhmpdplkmr2lwf8ekusaxzqntx7c9hp9utzcvkjcr',

  // Price of pinning, in satoshis per megabyte per year. Required: if this is
  // unset, payment validation fails closed (PS010 §7.3 F7).
  satsPerMb: process.env.SATS_PER_MB ? parseInt(process.env.SATS_PER_MB) : null,

  // Accept BCH payments. Set ACCEPT_BCH_PAYMENT=false to stop accepting claims.
  acceptBchPayment: process.env.ACCEPT_BCH_PAYMENT
    ? process.env.ACCEPT_BCH_PAYMENT !== 'false'
    : true,

  // domainName: 'https://pin.fullstack.cash'
  domainName: process.env.DOMAIN_NAME ? process.env.DOMAIN_NAME : 'http://localhost:5031',

  // Periodic pin retry tunables (Timer Controller + download queue)
  pinRetryBatchSize: process.env.PIN_RETRY_BATCH_SIZE
    ? parseInt(process.env.PIN_RETRY_BATCH_SIZE)
    : 30,
  pinRetryMaxTries: process.env.PIN_RETRY_MAX_TRIES
    ? parseInt(process.env.PIN_RETRY_MAX_TRIES)
    : 5,
  pinRetryIntervalMs: process.env.PIN_RETRY_INTERVAL_MS
    ? parseInt(process.env.PIN_RETRY_INTERVAL_MS)
    : 60000 * 10, // 10 minutes
  pinRetryDownloadConcurrency: process.env.PIN_RETRY_DOWNLOAD_CONCURRENCY
    ? parseInt(process.env.PIN_RETRY_DOWNLOAD_CONCURRENCY)
    : 10,
  pinRetryBackoffBaseMs: process.env.PIN_RETRY_BACKOFF_BASE_MS
    ? parseInt(process.env.PIN_RETRY_BACKOFF_BASE_MS)
    : 60000 * 10, // 10 minutes; nextRetryAt = now + base * 2^tries
  pinRetryQuarantineBudget: process.env.PIN_RETRY_QUARANTINE_BUDGET
    ? parseInt(process.env.PIN_RETRY_QUARANTINE_BUDGET)
    : 2,
  pinRetryQuarantineCooldownMs: process.env.PIN_RETRY_QUARANTINE_COOLDOWN_MS
    ? parseInt(process.env.PIN_RETRY_QUARANTINE_COOLDOWN_MS)
    : 60000 * 60 * 6, // 6 hours

  // END FILE PIN CONFIGURATION

  // END IPFS CONFIGURATION

  // Account Configuration
  disableNewAccounts: process.env.DISABLE_NEW_ACCOUNTS ? true : false,

  // Admin password
  adminPassword: process.env.ADMIN_PASSWORD
}
